  orderCategoryBlocks(extensionBlocks) {
    let categoryBlocks = blocks;
    let idx = 0;
    for (const block of extensionBlocks) {
      categoryBlocks = categoryBlocks.replace('%b' + idx + ">", block);
      idx++;
    }
    return [categoryBlocks];
  }

