  _decodeSound(soundBuffer) {
    const engine = this.runtime.audioEngine;
    if (!engine) {
      return Promise.reject(new Error('No Audio Context Detected'));
    }

    // Check for newer promise-based API
    return engine.decodeSoundPlayer({
      data: {
        buffer: soundBuffer
      }
    });
  }

